 3	public final class CountingSortTest {
 4	
 5	    private CountingSortTest() {
 6	    }
 7	
 8	    public static void main(String[] args) {
 9	        assertArrayEquals(
10	            new int[] {},
11	            CountingSort.sortedCopy(new int[] {})
12	        );
13	        assertArrayEquals(
14	            new int[] {-4, -1, 0, 0, 2, 2, 3, 3, 3, 5},
15	            CountingSort.sortedCopy(new int[] {2, 5, 3, 0, 2, 3, 0, 3, -4, -1})
16	        );
17	
18	        int[] output = new int[4];
19	        CountingSort.copyInto(new int[] {3, -1, 3, 0}, output);
20	        assertArrayEquals(new int[] {-1, 0, 3, 3}, output);
21	
22	        int[] values = {3, -1, 3, 0};
23	        CountingSort.sortInPlace(values);
24	        assertArrayEquals(new int[] {-1, 0, 3, 3}, values);
25	
26	        assertThrows(
27	            IllegalArgumentException.class,
28	            () -> CountingSort.copyInto(new int[] {1, 2}, new int[1])
29	        );
30	        assertThrows(
31	            NullPointerException.class,
32	            () -> CountingSort.sortedCopy(null)
33	        );
34	    }
35	
36	    private static void assertArrayEquals(int[] expected, int[] actual) {
37	        if (!Arrays.equals(expected, actual)) {
38	            throw new AssertionError(
39	                "Expected " + Arrays.toString(expected)
40	                    + " but was " + Arrays.toString(actual)
41	            );
42	        }
43	    }
44	
45	    private static void assertThrows(
46	        Class<? extends Throwable> expectedType,
47	        ThrowingRunnable action
48	    ) {
49	        try {
50	            action.run();
51	        } catch (Throwable throwable) {
52	            if (expectedType.isInstance(throwable)) {
53	                return;
54	            }
55	
56	            throw new AssertionError(
57	                "Expected " + expectedType.getSimpleName()
58	                    + " but caught " + throwable.getClass().getSimpleName(),
59	                throwable
60	            );
61	        }
62	
63	        throw new AssertionError(
64	            "Expected " + expectedType.getSimpleName() + " to be thrown."
65	        );
66	    }
67	
68	    @FunctionalInterface
69	    private interface ThrowingRunnable {
70	        void run();
71	    }
72	}

  1	import java.util.Objects;
  2	
  3	/**
  4	 * Stable counting sort for integer arrays.
  5	 */
  6	public final class CountingSort {
  7	
  8	    private CountingSort() {
  9	    }
 10	
 11	    /**
 12	     * Legacy wrapper retained for compatibility.
 13	     */
 14	    public static int[] countSort(int[] values) {
 15	        return sortedCopy(values);
 16	    }
 17	
 18	    /**
 19	     * Legacy wrapper retained for compatibility.
 20	     */
 21	    public static int[] sort(int[] values) {
 22	        return sortedCopy(values);
 23	    }
 24	
 25	    /**
 26	     * Returns a sorted copy of {@code values}.
 27	     */
 28	    public static int[] sortedCopy(int[] values) {
 29	        Objects.requireNonNull(values, "values");
 30	        int[] sortedValues = new int[values.length];
 31	        copyInto(values, sortedValues);
 32	        return sortedValues;
 33	    }
 34	
 35	    /**
 36	     * Writes the sorted contents of {@code input} into {@code output}.
 37	     */
 38	    public static void copyInto(int[] input, int[] output) {
 39	        Objects.requireNonNull(input, "input");
 40	        Objects.requireNonNull(output, "output");
 41	        requireSameLength(input, output);
 42	
 43	        if (input.length == 0) {
 44	            return;
 45	        }
 46	
 47	        int[] source = input == output ? input.clone() : input;
 48	        planSort(source, output).execute();
 49	    }
 50	
 51	    /**
 52	     * Sorts {@code values} in place.
 53	     */
 54	    public static void sortInPlace(int[] values) {
 55	        Objects.requireNonNull(values, "values");
 56	
 57	        if (values.length == 0) {
 58	            return;
 59	        }
 60	
 61	        copyInto(values, values);
 62	    }
 63	
 64	    private static SortOperation planSort(int[] input, int[] output) {
 65	        Range range = findRange(input);
 66	        int[] prefixCounts = buildPrefixCounts(input, range);
 67	        return new SortOperation(input, output, range, prefixCounts);
 68	    }
 69	
 70	    private static void requireSameLength(int[] input, int[] output) {
 71	        if (input.length != output.length) {
 72	            throw new IllegalArgumentException(
 73	                "Input and output arrays must have the same length."
 74	            );
 75	        }
 76	    }
 77	
 78	    private static Range findRange(int[] values) {
 79	        int minValue = values[0];
 80	        int maxValue = values[0];
 81	
 82	        for (int i = 1; i < values.length; i++) {
 83	            int value = values[i];
 84	            if (value < minValue) {
 85	                minValue = value;
 86	            }
 87	            if (value > maxValue) {
 88	                maxValue = value;
 89	            }
 90	        }
 91	
 92	        return new Range(minValue, maxValue);
 93	    }
 94	
 95	    private static int[] buildPrefixCounts(int[] values, Range range) {
 96	        int[] counts = new int[range.size()];
 97	
 98	        for (int value : values) {
 99	            counts[range.indexOf(value)]++;
100	        }
101	
102	        for (int i = 1; i < counts.length; i++) {
103	            counts[i] += counts[i - 1];
104	        }
105	
106	        return counts;
107	    }
108	
109	    private record SortOperation(
110	        int[] input,
111	        int[] output,
112	        Range range,
113	        int[] prefixCounts
114	    ) {
115	        private void execute() {
116	            for (int i = input.length - 1; i >= 0; i--) {
117	                int value = input[i];
118	                int countIndex = range.indexOf(value);
119	                output[prefixCounts[countIndex] - 1] = value;
120	                prefixCounts[countIndex]--;
121	            }
122	        }
123	    }
124	
125	    private record Range(int minValue, int maxValue) {
126	        private int size() {
127	            long size = (long) maxValue - minValue + 1;
128	            if (size > Integer.MAX_VALUE) {
129	                throw new IllegalArgumentException(
130	                    "Counting sort range is too large to index."
131	                );
132	            }
133	
134	            return (int) size;
135	        }
136	
137	        private int indexOf(int value) {
138	            return value - minValue;
139	        }
140	    }
141	}
